<template><div class="app-container governance-admin"><div class="toolbar"><h2>调解与徽章</h2><el-button @click="load">刷新</el-button></div><el-tabs v-model="tab" @tab-change="changeTab"><el-tab-pane label="调解工单" name="cases"/><el-tab-pane label="评审员管理" name="jurors"/><el-tab-pane label="统计与提醒" name="stats"/><el-tab-pane label="商家合作复核" name="merchants"/><el-tab-pane v-if="canBadges" label="成就徽章" name="badges"/></el-tabs><MerchantCases v-if="tab==='merchants'"/><Badges v-else-if="tab==='badges'"/>
<template v-else-if="tab==='cases'&&!detail"><el-alert title="城市负责人可在员工端接单，总部也可打开工单「接手初审」。发布裁决后双方接受即结案。有申诉时，筛选「总部复核中」查看并处理。" :closable="false"/><el-select v-model="status" clearable placeholder="全部状态" @change="page=1;load()" style="margin:18px 0"><el-option v-for="(v,k) in states" :key="k" :label="v" :value="k"/></el-select><el-table :data="data.cases?.rows||[]" v-loading="loading"><el-table-column prop="caseNo" label="工单号" min-width="230"/><el-table-column prop="city" label="城市" width="90"/><el-table-column prop="storeName" label="门店" min-width="160"/><el-table-column prop="category" label="类型"/><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.urgent==='1'?'danger':'info'">{{row.urgent==='1'?'紧急 · ':''}}{{states[row.status]}}</el-tag></template></el-table-column><el-table-column prop="acceptDeadline" label="接单时限" width="180"/><el-table-column label="操作" width="110"><template #default="{row}"><el-button link type="primary" @click="open(row.caseId)">{{row.status==='appealed'?'查看申诉':'查看工单'}}</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="data.cases?.total||0" :page-size="30" layout="prev,pager,next,total" @current-change="load"/></template>
<template v-else-if="tab==='cases'&&detail"><el-button @click="detail=null">返回工单列表</el-button><el-button @click="exportCase">导出完整记录</el-button><h3>{{detail.caseNo}} · {{states[detail.status]}}</h3><el-alert v-if="detail.status==='confirmation'" title="等待双方确认。双方均接受后结案，任一方提出申诉后可在此复核。" :closable="false"/><el-button v-if="detail.canHqReview" v-hasPermi="['kangaroo:mediation:edit']" type="primary" plain @click="reviewSection?.scrollIntoView({block:'center'})">去填写终局结果</el-button><el-descriptions :column="3" border><el-descriptions-item label="城市">{{detail.city}}</el-descriptions-item><el-descriptions-item label="订单">{{detail.orderNo}}</el-descriptions-item><el-descriptions-item label="处理负责人ID">{{detail.hqHandling?'总部初审':detail.handlerId||'待接单'}}</el-descriptions-item><el-descriptions-item label="事件类型">{{detail.category}}</el-descriptions-item><el-descriptions-item label="联系号码">{{detail.phone}}</el-descriptions-item><el-descriptions-item label="发生时间">{{detail.incidentAt}}</el-descriptions-item></el-descriptions><section><h3>事件经过及诉求</h3><p>{{detail.narrative}}</p><p>{{detail.claims}}</p><div class="attachments"><el-button v-for="f in detail.evidence" :key="f.fileId" @click="file(f.fileId)">{{f.redacted==='1'?'脱敏 · ':''}}{{f.originalName}}</el-button></div></section><section v-if="detail.verification"><h3>核实记录</h3><p>{{verification}}</p></section><HqFirstReview :key="detail.caseId" :detail="detail" :busy="busy" @command="command"/><section v-if="detail.decision"><h3>裁决与执行</h3><p>责任判定：{{detail.decision}}</p><p>依据：{{detail.basis}}</p><p>措施：{{detail.measures}}</p><p>执行时限：{{detail.executeDeadline}}</p><p>信用 / 处罚影响：{{detail.creditImpact}}</p><p v-if="detail.juryReason">评审{{detail.juryAdopted==='1'?'已采纳':'未采纳'}}：{{detail.juryReason}}</p></section><section v-if="detail.appeal"><h3>二次申诉</h3><p>{{detail.appeal}}</p></section><section v-if="detail.canHqReview" ref="reviewSection"><h3>总部终局复核</h3><el-input v-model="result" type="textarea" :rows="6" maxlength="10000" placeholder="至少20字，说明复核事实、依据及最终处理结果"/><el-button v-hasPermi="['kangaroo:mediation:edit']" type="primary" :loading="busy" @click="command('hqReview',{result})">提交终局结果并关闭</el-button></section><section v-if="detail.hqResult"><h3>总部复核结论</h3><p>{{detail.hqResult}}</p></section>
<section v-if="detail.votes?.length"><h3>评审记录（评审员身份仅总部可见）</h3><el-table :data="detail.votes"><el-table-column prop="appUserId" label="评审员ID"/><el-table-column prop="jurorKind" label="身份"/><el-table-column prop="choice" label="投票"/><el-table-column prop="reason" label="理由" min-width="250"/><el-table-column prop="assessmentNote" label="评定依据"/>
<el-table-column label="个人意见采纳" width="150"><template #default="{row}"><el-select v-if="canRecordAdoption&&row.choice&&row.valid==='1'" v-model="adoptionValues[row.voteId]" placeholder="待核定"><el-option label="未采纳" value="0"/><el-option label="已采纳" value="1"/></el-select><span v-else>{{row.cityAdopted==='1'?'已采纳':row.cityAdopted==='0'?'未采纳':'待核定'}}</span></template></el-table-column><el-table-column label="评定"><template #default="{row}"><el-button v-if="!row.assessmentNote&&row.choice&&detail.jury?.status==='closed'" v-hasPermi="['kangaroo:mediation:edit']" link type="primary" @click="vote=row;assessment={valid:true,quality:false,assessmentKind:'valid',note:''}">核验评审质量</el-button><span v-else>{{row.quality==='1'?'优质':row.valid==='1'?'有效':'未投票或无效'}}</span></template></el-table-column></el-table><el-form v-if="canRecordAdoption&&adoptionVotes.length" label-position="top"><el-form-item label="逐条采纳核定依据"><el-input v-model="adoptionNote" type="textarea" maxlength="500" placeholder="至少5字，说明本次补录或更正的依据"/></el-form-item><el-button v-hasPermi="['kangaroo:mediation:edit']" :disabled="!adoptionReady||adoptionNote.trim().length<5" :loading="busy" @click="command('adoption',{adoptedVoteIds:selectedAdoptionIds(),note:adoptionNote})">保存个人采纳结果</el-button></el-form><el-form v-if="vote" label-position="top"><el-form-item label="评审有效性"><el-select v-model="assessment.assessmentKind" @change="assessment.valid=$event==='valid';assessment.quality=false"><el-option label="有效评审" value="valid"/><el-option label="经核实为敷衍投票" value="perfunctory"/><el-option label="其他无效情况" value="invalid"/></el-select><p>理由选填。缺席和空理由不自动判定为敷衍，敷衍须写明核验事实。</p></el-form-item><el-form-item label="优质评审"><el-switch v-model="assessment.quality" :disabled="!assessment.valid||!vote.reason||!vote.reason.trim()" active-text="额外奖励10积分"/><p>优质评审须填写理由，由总部核实其对判断事实的参考价值。</p></el-form-item><el-form-item label="评定依据"><el-input v-model="assessment.note" type="textarea" :rows="3" maxlength="500"/></el-form-item><el-button type="primary" :loading="busy" @click="assess">保存评定</el-button><el-button @click="vote=null">取消</el-button></el-form></section>
<section v-if="detail.status!=='closed'" v-hasPermi="['kangaroo:mediation:edit']"><h3>督导跟进</h3><el-input v-model="contact" type="textarea" :rows="3" placeholder="登记已完成的电话或其他联络，至少10字"/><el-button :loading="busy" @click="command('contact',{note:contact})">保存联络记录</el-button><template v-if="detail.canHqReassign"><h4>转交本城负责人</h4><el-input-number v-model="nextHandler" :min="1" :controls="false" placeholder="城市负责人的小程序账号ID" style="width:220px"/><el-input v-model="transferNote" placeholder="转交原因，10–500字" style="max-width:600px;margin-left:12px"/><el-button :loading="busy" @click="nextHandler?command('reassign',{handlerId:nextHandler,note:transferNote}):ElMessage.warning('请先填写要转交的城市负责人的小程序账号ID')">转交</el-button><p>填小程序账号 ID（「员工授权」列表「小程序账号（ID）」一列里的 ID 数字），不是后台登录账号。只能转给负责本单城市、且和这家门店、双方当事人都没有关联的城市负责人。转交后对方会收到站内通知：还没接单的工单要对方在小程序里接单，已接单的由对方直接接着处理，原负责人不能再操作；原处理记录保留。</p></template></section>
<section><h3>不可删除的处理记录</h3><el-table :data="detail.log"><el-table-column prop="createTime" label="时间" width="180"/><el-table-column prop="actor" label="操作人"/><el-table-column prop="action" label="操作"/><el-table-column prop="fromState" label="之前"/><el-table-column prop="toState" label="之后"/><el-table-column prop="note" label="记录" min-width="300"/></el-table></section><section v-if="['confirmation','appealed','closed'].includes(detail.status)"><h3>实际执行登记</h3><el-input v-model="execution" type="textarea" :rows="3" placeholder="记录实际退款单号、补发凭证或其他执行结果，至少10字"/><el-button v-hasPermi="['kangaroo:mediation:edit']" :loading="busy" @click="command('execution',{note:execution})">保存执行记录</el-button></section></template>
<template v-else-if="tab==='jurors'"><el-alert title="用户或商家在小程序自愿加入。抽取时重新校验业务经历、合作时间、评分、违规和利益回避条件。" :closable="false"/><el-table :data="jurors.rows||[]"><el-table-column prop="appUserId" label="账号ID"/><el-table-column prop="nickname" label="昵称"/><el-table-column prop="kind" label="身份"/><el-table-column prop="storeId" label="商家门店ID"/><el-table-column prop="creditScore" label="信用分"/><el-table-column prop="willing" label="参与意愿"/><el-table-column label="评审池"><template #default="{row}">{{row.coreMember?'核心评审员':row.coreEligible?'符合核心条件，待加入':'普通评审员'}}</template></el-table-column><el-table-column prop="suspendedUntil" label="暂停至"/><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.disqualified!=='1'" v-hasPermi="['kangaroo:mediation:edit']" link type="danger" @click="sanctioned=row">违规处理</el-button><span v-else>资格已暂停</span><el-button v-hasPermi="['kangaroo:mediation:edit']" link @click="openRestore(row)">核对恢复记录</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="juryPage" :total="jurors.total||0" :page-size="30" layout="prev,pager,next,total" @current-change="loadJurors"/><el-form v-if="sanctioned" label-position="top"><h3>暂停评审资格 {{sanctioned.nickname}}</h3><el-form-item label="已核实的违规类型"><el-select v-model="sanction.kind"><el-option label="泄露调解信息" value="leakage"/><el-option label="核实存在偏袒" value="bias"/></el-select></el-form-item><el-form-item label="已核实的违规事实"><el-input v-model="sanction.note" type="textarea" :rows="4"/></el-form-item><el-form-item label="信用扣分"><el-input-number v-model="sanction.deduction" :min="1" :max="100"/></el-form-item><el-button type="danger" :loading="busy" @click="punish">暂停资格并记录</el-button><el-button @click="sanctioned=null">取消</el-button></el-form>
<el-form v-if="restoring" label-position="top"><h3>核对评审资格处理 {{restoring.nickname}}</h3><el-table :data="sanctionHistory"><el-table-column prop="createTime" label="处理时间" width="180"/><el-table-column prop="note" label="核实依据"/><el-table-column label="状态"><template #default="{row}">{{row.active?'待核对':'已撤销'}}</template></el-table-column></el-table><template v-if="activeSanctions.length"><el-form-item label="需要撤销的原处理记录"><el-select v-model="restoration.logId" placeholder="选择原处理记录"><el-option v-for="record in activeSanctions" :key="record.logId" :value="record.logId" :label="sanctionLabel(record)"/></el-select></el-form-item><p v-if="restoreCreditUnknown">旧记录未保存实际扣分，信用分需另行核对。</p><el-form-item label="恢复核验依据"><el-input v-model="restoration.note" type="textarea" maxlength="500" placeholder="至少10字，说明原处理为何撤销"/></el-form-item><el-button type="primary" :disabled="!restoration.logId||restoration.note.trim().length<10" :loading="busy" @click="restoreQualification">撤销对应处理</el-button><p>恢复后按当前业务、信用和暂停期限重新核对资格，金牌仍按真实条件评定。</p></template><p v-else>没有尚未撤销的资格处理记录。</p><el-button @click="restoring=null">关闭</el-button></el-form></template>
<template v-else-if="tab==='stats'"><el-descriptions :column="3" border><el-descriptions-item label="工单总量">{{data.stats?.totals?.cases||0}}</el-descriptions-item><el-descriptions-item label="闭环率">{{percent(data.stats?.totals?.closed,data.stats?.totals?.cases)}}</el-descriptions-item><el-descriptions-item label="平均响应">{{data.stats?.totals?.responseMinutes==null?'暂无数据':Number(data.stats.totals.responseMinutes).toFixed(1)+'分钟'}}</el-descriptions-item><el-descriptions-item label="评审采纳率">{{percent(data.stats?.totals?.adopted,data.stats?.totals?.juryCases)}}</el-descriptions-item></el-descriptions><h3>类型分布</h3><el-table :data="data.stats?.types||[]"><el-table-column prop="category" label="类型"/><el-table-column prop="n" label="工单数"/></el-table><h3>需跟进的提醒</h3><el-alert title="站内通知自动发送；紧急短信/电话需要实际联络。未配置的外部通道不会标记为已发送。" :closable="false"/><el-table :data="data.stats?.urgentQueue||[]"><el-table-column prop="caseNo" label="工单号"/><el-table-column prop="content" label="内容" min-width="300"/><el-table-column prop="status" label="状态"/><el-table-column label="查看"><template #default="{row}"><el-button link type="primary" @click="tab='cases';open(row.caseId)">打开</el-button></template></el-table-column></el-table></template>
</div></template>
<script setup>
import {ref,computed,onMounted} from 'vue';import request from '@/utils/request';import {ElMessage} from 'element-plus';import Badges from './Badges.vue'
import MerchantCases from './MerchantCases.vue'
import HqFirstReview from './HqFirstReview.vue'
import {checkPermi} from '@/utils/permission'
const canBadges=checkPermi(['kangaroo:memberlevel:query'])
const states={pending:'待接单',accepted:'已接单',verifying:'核实中',ready:'待裁决',jury:'大众评审中',confirmation:'待双方确认',appealed:'总部复核中',closed:'已关闭'}
// 转交对象默认留空：之前默认 1，不改就点会转给 1 号账号
const reviewSection=ref(null)
const contact=ref(''),nextHandler=ref(),transferNote=ref('')
const tab=ref('cases'),data=ref({}),page=ref(1),status=ref(''),loading=ref(false),busy=ref(false),detail=ref(null),result=ref(''),execution=ref(''),vote=ref(null),assessment=ref({valid:true,quality:false,assessmentKind:'valid',note:''}),jurors=ref({}),juryPage=ref(1),sanctioned=ref(null),sanction=ref({kind:'leakage',note:'',deduction:10})
const adoptionValues=ref({}),adoptionNote=ref(''),restoring=ref(null),sanctionHistory=ref([]),restoration=ref({logId:null,note:''})
const adoptionVotes=computed(()=>(detail.value?.votes||[]).filter(v=>v.choice&&v.valid==='1'))
const canRecordAdoption=computed(()=>detail.value?.jury?.status==='closed'&&['confirmation','appealed','closed'].includes(detail.value?.status))
const adoptionReady=computed(()=>adoptionVotes.value.every(v=>['0','1'].includes(adoptionValues.value[v.voteId])))
const selectedAdoptionIds=()=>adoptionVotes.value.filter(v=>adoptionValues.value[v.voteId]==='1').map(v=>v.voteId)
const activeSanctions=computed(()=>sanctionHistory.value.filter(record=>Number(record.active)===1))
const restoreCreditUnknown=computed(()=>!!restoration.value.logId&&activeSanctions.value.find(record=>record.logId===restoration.value.logId)?.creditDelta==null)
const sanctionLabel=record=>({juror_leakage:'泄露信息',juror_bias:'核实偏袒',juror_disqualified:'历史资格处理'}[record.action]||record.action)+' · '+record.createTime
async function openRestore(row){busy.value=true;try{sanctionHistory.value=(await api('/jurors/'+row.appUserId+'/sanctions')).data;restoration.value={logId:null,note:''};restoring.value=row}finally{busy.value=false}}
async function restoreQualification(){busy.value=true;try{await api('/jurors/'+restoring.value.appUserId+'/restore','post',restoration.value);ElMessage.success('原处理已撤销，资格按当前条件核对');restoring.value=null;await loadJurors()}finally{busy.value=false}}
const api=(path='',method='get',body)=>request({url:'/kangaroo/governance'+path,method,...(method==='get'?{params:body}:{data:body})})
const percent=(a,b)=>b?((a||0)/b*100).toFixed(1)+'%':'暂无数据'
const verification=computed(()=>{try{const r=JSON.parse(detail.value.verification);return ['userStatement','merchantStatement','evidenceList','finding'].map((k,i)=>['用户陈述','店家陈述','核实证据','初步判断'][i]+'：'+r[k]).join('\n')}catch(e){return detail.value.verification}})
async function load(){loading.value=true;try{data.value=(await api('','get',{pageNum:page.value,status:status.value})).data;if(detail.value)await open(detail.value.caseId)}finally{loading.value=false}}
async function open(id){detail.value=(await api('/cases/'+id)).data;result.value='';vote.value=null;adoptionValues.value=Object.fromEntries(adoptionVotes.value.map(v=>[v.voteId,['0','1'].includes(v.cityAdopted)?v.cityAdopted:'']));adoptionNote.value=''}
async function command(action,body){busy.value=true;try{await api('/cases/'+detail.value.caseId+'/'+action,'post',body);ElMessage.success('已保存，各端可查看最新结果');await open(detail.value.caseId)}finally{busy.value=false}}
async function assess(){busy.value=true;try{await api('/votes/'+vote.value.voteId,'post',assessment.value);ElMessage.success('评定已保存，积分同步完成');await open(detail.value.caseId)}finally{busy.value=false}}
async function loadJurors(){jurors.value=(await api('/jurors','get',{pageNum:juryPage.value})).data}
function changeTab(t){if(t==='jurors')loadJurors();else if(t!=='badges')load()}
async function punish(){busy.value=true;try{await api('/jurors/'+sanctioned.value.appUserId+'/sanction','post',sanction.value);sanctioned.value=null;await loadJurors()}finally{busy.value=false}}
async function file(id){const r=(await api('/files/'+id)).data;window.open(import.meta.env.VITE_APP_BASE_API+r.url,'_blank','noopener')}
async function exportCase(){const r=await api('/export/'+detail.value.caseId);const blob=new Blob([JSON.stringify(r.data,null,2)],{type:'application/json;charset=utf-8'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=detail.value.caseNo+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)}
onMounted(load)
</script><style scoped>.toolbar{display:flex;align-items:center;justify-content:space-between}.toolbar h2{font-size:23px}.el-pagination{margin:20px 0}section{padding:20px 0;border-bottom:1px solid #e8e2d7}section p{white-space:pre-wrap;line-height:1.8;max-width:85ch;overflow-wrap:anywhere}section .el-button{margin-top:12px}.attachments{display:flex;flex-wrap:wrap;gap:8px}.el-form{max-width:800px;margin:20px 0}</style>
